begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('d6320000-0000-4000-8000-000000000001','category-owner@example.test',now()),
 ('d6320000-0000-4000-8000-000000000002','category-outsider@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d6320000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Category registration','category-registration',gen_random_uuid())::text,true);
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','seller@category.test','')::text,true);
select set_config('test.agreement',publish_seller_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'Synthetic terms','Test only','en',false)::text,true);
select record_agreement_evidence(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,current_setting('test.agreement')::uuid,'Signed test');
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),null,(current_store_policy(current_setting('test.tenant')::uuid)->'policy')||'{"vatModeConsignmentPrivate":"consignment_margin"}');
select set_config('test.cat',create_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),'Books A','{"sv":"Böcker","en":"Books"}')::text,true);
select set_config('test.other',create_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),'Books B','{"sv":"Böcker","en":"Books"}')::text,true);
select set_item_type(current_setting('test.tenant')::uuid,'test_book',jsonb_build_object('labels','{"en":"Test book"}'::jsonb,'suggestedCategoryId',current_setting('test.cat'),'attributes','[{"slug":"description","sort":0}]'::jsonb));
select is((select t->>'suggested_category_id' from jsonb_array_elements(attribute_vocabulary(current_setting('test.tenant')::uuid)->'types') t where t->>'slug'='test_book'),current_setting('test.cat'),'type default stores ID despite ambiguous translations');
select set_config('test.session',create_reception_session(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid)::text,true);
select set_config('test.request',gen_random_uuid()::text,true);
select set_config('test.result',quick_receive_categorized(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,current_setting('test.session')::uuid,current_setting('test.seller')::uuid,0,'{"description":"Book"}',12000,null,'test_book',null,current_setting('test.other')::uuid)::text,true);
select is((select category_id::text from item_category_links where item_id=(current_setting('test.result')::jsonb->>'itemId')::uuid order by seq desc limit 1),current_setting('test.other'),'explicit category overrides type default');
select update_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.other')::uuid,0,'Reading B','{"en":"Reading"}',false);
select lives_ok($$select quick_receive_categorized(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,current_setting('test.session')::uuid,current_setting('test.seller')::uuid,0,'{"description":"Book"}',12000,null,'test_book',null,current_setting('test.other')::uuid)$$,'lost reply replays after rename and deactivation');
select throws_ok($$select quick_receive_categorized(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,current_setting('test.session')::uuid,current_setting('test.seller')::uuid,0,'{"description":"Book"}',12000,null,'test_book',null,current_setting('test.cat')::uuid)$$,'P0001','REQUEST_CONFLICT','retry cannot change chosen ID');
select is((items_search_page(current_setting('test.tenant')::uuid,jsonb_build_object('categoryId',current_setting('test.other')),'title','asc',25,0)->>'total')::int,1,'ID filter retains renamed inactive category');
select is((items_search_page(current_setting('test.tenant')::uuid,jsonb_build_object('categoryId',current_setting('test.cat')),'title','asc',25,0)->>'total')::int,0,'shared translation does not conflate categories');
select is((stock_report_by_category(current_setting('test.tenant')::uuid,current_date,current_date,null)->'categories'->0->>'categoryId'),current_setting('test.other'),'report groups by ID');
select set_config('test.session2',create_reception_session(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid)::text,true);
select throws_ok($$select quick_receive_categorized(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.session2')::uuid,current_setting('test.seller')::uuid,0,'{"description":"Denied"}',12000,null,null,null,current_setting('test.other')::uuid)$$,'P0001','CATEGORY_NOT_FOUND','inactive category cannot be newly selected');
select is((select count(*) from items where origin_id=current_setting('test.session2')::uuid),0::bigint,'invalid selection rolls back all acceptance');
select quick_receive_categorized(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.session2')::uuid,current_setting('test.seller')::uuid,0,'{"description":"No category"}',12000,null,'test_book',null,null);
select is((items_search_page(current_setting('test.tenant')::uuid,'{"categoryId":"none"}','title','asc',25,0)->>'total')::int,1,'explicit none stays unlinked despite type default');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'category',current_setting('test.cat'))->>'ok','false','type default prevents category deletion');
select set_config('test.bag',receive_bag_with_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,'',current_setting('test.agreement')::uuid)::text,true);
select set_config('test.bag_session',create_bag_reception(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,current_setting('test.bag')::uuid)::text,true);
select set_config('test.bag_result',quick_receive_categorized(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.bag_session')::uuid,current_setting('test.seller')::uuid,0,'{"description":"Bag book"}',18000,current_setting('test.bag')::uuid,'test_book',null,current_setting('test.cat')::uuid)::text,true);
select is((select category_id::text from item_category_links where item_id=(current_setting('test.bag_result')::jsonb->>'itemId')::uuid order by seq desc limit 1),current_setting('test.cat'),'bag reception shares explicit category selection');
select update_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.cat')::uuid,0,'Reading A','{"en":"Reading"}',true);
select is(jsonb_array_length(stock_report_by_category(current_setting('test.tenant')::uuid,current_date,current_date,null)->'categories'),3,'same translated names and unlinked goods remain separate ID groups');
select set_item_type(current_setting('test.tenant')::uuid,'legacy_match','{"labels":{"en":"Legacy"},"suggestedCategory":"Reading A","attributes":[]}');
select is((select t->>'suggested_category_id' from jsonb_array_elements(attribute_vocabulary(current_setting('test.tenant')::uuid)->'types') t where t->>'slug'='legacy_match'),current_setting('test.cat'),'legacy type writes map an unambiguous current name');
select set_item_type(current_setting('test.tenant')::uuid,'legacy_unmatched','{"labels":{"en":"Unmatched"},"suggestedCategory":"Not in registry","attributes":[]}');
select is((select t->>'suggested_category' from jsonb_array_elements(attribute_vocabulary(current_setting('test.tenant')::uuid)->'types') t where t->>'slug'='legacy_unmatched'),'Not in registry','unmatched type text remains available for correction');
select set_config('test.profile',(select t::text from jsonb_array_elements(attribute_vocabulary(current_setting('test.tenant')::uuid)->'types') t where t->>'slug'='test_book'),true);
select set_config('test.payload',jsonb_build_object('labels','{"en":"Test book"}'::jsonb,'suggestedCategoryId',current_setting('test.other'),'active',true,'attributes','[]'::jsonb)::text,true);
select throws_ok($$select update_item_type(current_setting('test.tenant')::uuid,'test_book',current_setting('test.profile')::jsonb,current_setting('test.payload')::jsonb)$$,'P0001','CATEGORY_NOT_FOUND','type editor rejects a newly selected inactive category');
select throws_ok($$select items_search_page(current_setting('test.tenant')::uuid,'{"categoryId":"Reading"}','title','asc',25,0)$$,'P0001','INVALID_INPUT','ID filter rejects free text');
select set_config('test.foreign',create_tenant('Other category store','other-category-store',gen_random_uuid())::text,true);
select set_config('test.foreign_cat',create_item_category(current_setting('test.foreign')::uuid,gen_random_uuid(),'Foreign','{"en":"Foreign"}')::text,true);
select throws_ok($$select set_item_type(current_setting('test.tenant')::uuid,'cross_store',jsonb_build_object('labels','{"en":"Cross store"}'::jsonb,'suggestedCategoryId',current_setting('test.foreign_cat')))$$,'P0001','CATEGORY_NOT_FOUND','category default is tenant-bound even for owner of both stores');
select throws_ok($$select quick_receive_categorized(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.session2')::uuid,current_setting('test.seller')::uuid,0,'{"description":"Denied"}',12000,null,null,null,current_setting('test.foreign_cat')::uuid)$$,'P0001','CATEGORY_NOT_FOUND','registration cannot use another store category');
reset role;
select is(komisio_private.item_title(current_setting('test.tenant')::uuid,(current_setting('test.bag_result')::jsonb->>'itemId')::uuid)->>'category','Reading A','current linked name reaches product and price-evidence readers');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d6320000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok($$select quick_receive_categorized(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.session2')::uuid,current_setting('test.seller')::uuid,0,'{"description":"Denied"}',12000,null,null,null,null)$$,'42501','FORBIDDEN','outsider cannot register or replay');
select throws_ok($$select stock_report_by_category(current_setting('test.tenant')::uuid,current_date,current_date,null)$$,'42501','FORBIDDEN','category report enforces membership');
select * from finish();
rollback;
